import { Component, Element, Host, Prop, State, Watch, h } from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";
import { generateShortID } from "../../utils/function-helper";
import { getCssRulesForSentimentCard } from "../../utils/sentiments";
import { hasNamedSlot } from "../../utils/slot";

/**
 * Maps semantic col values to responsive data-col-span attributes.
 * Structure: { base, sm, xs } where:
 * - base: default desktop span (data-col-span)
 * - sm: tablet span 554-783px (data-sm-col-span)
 * - xs: mobile span ≤553px (data-xs-col-span)
 */
const COL_SPAN_MAP: Record<string, { base: number; sm: number; xs: number }> = {
	"1/4": { base: 3, sm: 6, xs: 12 },
	"1/3": { base: 4, sm: 6, xs: 12 },
	"1/2": { base: 6, sm: 12, xs: 12 },
	"2/3": { base: 8, sm: 12, xs: 12 },
	"3/4": { base: 9, sm: 12, xs: 12 },
	full: { base: 12, sm: 12, xs: 12 },
};

/**
 * @since 0.0.12
 * @status stable
 *
 * @description Cards group related information in a flexible-size containers.
 * Container cards typically group multiple basic cards (with related content and actions) in a single container.
 * Basic cards typically contain a few short, related pieces of information and can be interactive or non-interactive.
 * If there are multiple cards in a row and the content height varies, the height of all the cards in the row match the height of the tallest card.
 *
 * @slot image - The card's image.
 * @slot - The card's body.
 * @slot header - The card's header
 * @slot footer - The card's footer.
 *
 * @part base - The component's base wrapper.
 * @part image - The card's image, if present.
 * @part header - The card's header, if present.
 * @part body - The card's body.
 * @part footer - The card's footer, if present.
 */

@Component({
	tag: "hbr-card",
	styleUrl: "card.scss",
	shadow: true,
})
export class Card {
	card: HTMLElement;
	sheet: CSSStyleSheet = new CSSStyleSheet();

	@Element() host: HTMLHbrCardElement;

	@State() hasFooter = false;
	@State() hasImage = false;
	@State() hasHeader = false;
	@State() uuid: string = generateShortID();

	/** for interactive cards, set to true to disable */
	@Prop({ reflect: true }) disabled = false;

	/** card selected state */
	@Prop({ reflect: true }) selected = false;

	/** selectable card */
	@Prop({ reflect: true }) selectable = false;

	/** Sentiment determines the top border accent color. Cards with sentiment accents are typically paired with a status tag for accessibility purposes. */
	@Prop({ reflect: true }) sentiment:
		| "success"
		| "positive"
		| "neutral"
		| "info"
		| "low-warning"
		| "warning"
		| "severe-warning"
		| "danger"
		| "negative" // Magnetic specific
		| "excellent"
		| "dormant"
		| "in-progress"
		| string;

	@Prop() tabIndexNumber: number;

	/** Container card */
	@Prop({ reflect: true }) container: boolean;

	/**
	 * Column span for container cards in dashboard grids.
	 * Semantic fractions that map to responsive data-col-span attributes.
	 * - "1/4": quarter width (3 cols desktop, 6 tablet, 12 mobile)
	 * - "1/3": third width (4 cols desktop, 6 tablet, 12 mobile)
	 * - "1/2": half width (6 cols desktop, 12 tablet, 12 mobile)
	 * - "2/3": two-thirds (8 cols desktop, 12 tablet, 12 mobile)
	 * - "3/4": three-quarters (9 cols desktop, 12 tablet, 12 mobile)
	 * - "full": full width (12 cols at all breakpoints)
	 */
	@Prop({ reflect: true }) col: "1/4" | "1/3" | "1/2" | "2/3" | "3/4" | "full";

	/** Systematically set responsive column spans */
	@Prop() span: { base: number; sm: number; xs: number };

	/** Accessibility aria-labelledby attribute  - deprecate candidate. Use "aria={arialabelledby: value}" prop instead. */
	@Prop() arialabelledby: string;

	/** Attributes related to screen readers. */
	@Prop() aria: { labelledby: string };

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
		this.applyColSpanAttributes();
	}

	@Watch("col")
	handleColChange() {
		this.applyColSpanAttributes();
	}

	@Watch("span")
	handleSpanChange() {
		this.applyColSpanAttributes();
	}

	/**
	 * Applies responsive data-col-span attributes.
	 * Priority: col prop > span prop (col is user-locked)
	 */
	private applyColSpanAttributes() {
		// col prop takes precedence (user-locked)
		const spans = (this.col && COL_SPAN_MAP[this.col]) || this.span;

		if (!spans) {
			this.host.removeAttribute("data-col-span");
			this.host.removeAttribute("data-sm-col-span");
			this.host.removeAttribute("data-xs-col-span");
			return;
		}

		if (spans.base != null)
			this.host.setAttribute("data-col-span", spans.base.toString());
		if (spans.sm != null)
			this.host.setAttribute("data-sm-col-span", spans.sm.toString());
		if (spans.xs != null)
			this.host.setAttribute("data-xs-col-span", spans.xs.toString());
	}

	componentDidLoad() {
		/** A11y for SR users */
		const header = this.host.querySelector("[role='heading']");
		if (header) {
			if (!header.id) {
				header.id = `hbr-card--${this.uuid}`;
				if (!this.host.getAttribute("aria-labelledby")) {
					this.host.setAttribute("aria-labelledby", header.id);
				}
			}
		}
	}

	handleSlotChange() {
		this.hasImage = hasNamedSlot(this.host, "image");
		this.hasHeader = hasNamedSlot(this.host, "header");
		this.hasFooter = hasNamedSlot(this.host, "footer");
	}

	handleKeyDown(event) {
		if (event.key === "Enter") {
			this.host.click();
		}
	}

	render() {
		const props = {
			tabIndex: this.selectable
				? this.tabIndexNumber !== undefined
					? this.tabIndexNumber
					: 0
				: null,
			onKeyDown: this.selectable ? this.handleKeyDown.bind(this) : null,
		};
		const _arialabelledby = this.aria?.labelledby || this.arialabelledby;
		const { sentiment, disabled } = this;

		const a11y = {};
		if (_arialabelledby) {
			a11y["aria-labelledby"] = _arialabelledby;
		}
		/** Updating to add magnetic token and also update the color align to magnetic guideline */

		if (this.host && this.sentiment) {
			this.sheet.replaceSync(`
				:host {
					${getCssRulesForSentimentCard({
						sentiment: this.sentiment,
						disabled,
					})}
				}
			`);
			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}

		return (
			<Host {...a11y}>
				{sentiment && <div class="card__accent" part="accent" />}
				<div
					ref={(el) => {
						this.card = el;
					}}
					part="base"
					class={{
						card: true,
						"card--has-image": this.hasImage,
						"card--has-header": this.hasHeader,
						"card--has-footer": this.hasFooter,
						"card--is-disabled": this.disabled,
						"card--is-selectable": this.selectable,
						"card--is-selected": this.selected,
						"card--has-sentiment": !!sentiment,
						"card--basic": !this.container,
						"card--container hbr-css__layout-col-md": this.container,
					}}
					{...props}
				>
					<div part="image" class="card__image">
						<slot name="image" onSlotchange={this.handleSlotChange} />
					</div>
					<div part="header" class="card__header">
						<slot name="header" onSlotchange={this.handleSlotChange} />
					</div>
					<div part="body" class="card__body">
						<slot />
					</div>

					<div part="footer" class="card__footer">
						<slot name="footer" onSlotchange={this.handleSlotChange} />
					</div>
				</div>
			</Host>
		);
	}
}
